#!/usr/bin/env python3
"""Invented shared documents. --check compares every generated byte without writing anything.

Verdicts are declared by hand; the Factory tests replay them against its validator/register.
The site can replay the same manifest with its own resolver and fixed clock.
"""
from __future__ import annotations

import argparse
import copy
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
KEY = 'PI-00TT9T81N'  # Synthetic C0 item key (sequence 900000001), no real catalogue.
ITEM = '00000000-0000-4000-8000-000000000001'


def generated() -> dict[str, bytes]:
    output, cases = {}, []
    base = {'contract_version': 'product_metrics_daily.v2', 'up_to': '2026-11-26', 'rows': [
        {'date': '2026-11-25', 'public_item_key': KEY, 'views': 7, 'add_to_cart': 2, 'quote_start': 1, 'quote_submit': 0}]}

    def write(name, value):
        output[name] = (json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':')) + '\n').encode('utf-8')

    def case(name, code, change=lambda d: None, depuis=None):
        doc = copy.deepcopy(base)
        change(doc)
        filename = 'documents/' + name + '.json'
        write(filename, doc)
        cases.append({'name': name, 'documents': [filename], 'verdicts': [code], 'depuis': depuis})

    case('accepted', 'ACCEPTED')
    case('empty', 'ACCEPTED', lambda d: d.update(rows=[]))
    case('extra_member', 'KEY_UNKNOWN', lambda d: d['rows'][0].update(session='invented'))
    case('extra_envelope_member', 'KEY_UNKNOWN', lambda d: d.update(visitor='invented'))
    case('negative', 'METRIC_INVALID', lambda d: d['rows'][0].update(views=-1))
    case('boolean', 'METRIC_INVALID', lambda d: d['rows'][0].update(views=True))
    case('float', 'METRIC_INVALID', lambda d: d['rows'][0].update(views=1.0))
    case('text', 'METRIC_INVALID', lambda d: d['rows'][0].update(views='1'))
    case('day_not_closed', 'DAY_NOT_CLOSED', lambda d: d.update(up_to='2026-11-27'))
    case('before_depuis', 'DATE_OUT_OF_RANGE', depuis='2026-11-26')
    case('after_up_to', 'DATE_OUT_OF_RANGE', lambda d: d['rows'][0].update(date='2026-11-27'))
    case('unsorted', 'ROWS_UNSORTED', lambda d: d['rows'].append({**d['rows'][0], 'date': '2026-11-24'}))
    case('duplicate', 'ROW_DUPLICATE', lambda d: d['rows'].append(copy.deepcopy(d['rows'][0])))
    case('too_many', 'ROWS_TOO_MANY', lambda d: d.update(rows=d['rows'] * 5001))
    case('unknown_item', 'ITEM_UNKNOWN', lambda d: d['rows'][0].update(public_item_key='PI-00TT9T82Y'))
    restated = copy.deepcopy(base)
    restated['rows'][0]['views'] += 1
    # A new day sorts before the conflicting one: NOTHING of this second lot may enter.
    restated['rows'].insert(0, {**restated['rows'][0], 'date': '2026-11-24'})
    write('documents/conflict.json', restated)
    cases.append({'name': 'conflict', 'documents': ['documents/accepted.json', 'documents/conflict.json'],
                  'verdicts': ['ACCEPTED', 'METRICS_CONFLICT'], 'depuis': None})
    write('VERDICTS.json', {'label': 'STAGING_FIXTURE', 'now_utc': '2026-11-27T12:00:00Z',
                            'resolve_items': {KEY: ITEM}, 'cases': cases})
    return output


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    expected = generated()
    if args.check:
        actual = {str(p.relative_to(ROOT)): p.read_bytes() for p in (ROOT / 'documents').glob('*.json')}
        if (ROOT / 'VERDICTS.json').exists():
            actual['VERDICTS.json'] = (ROOT / 'VERDICTS.json').read_bytes()
        differences = sorted(key for key in actual.keys() | expected.keys() if actual.get(key) != expected.get(key))
        if differences:
            print('DIFFERENCES: ' + ', '.join(differences))
            return 1
        print(f'OK --check : {len(expected)} fichiers identiques octet pour octet')
        return 0
    for name, content in expected.items():
        path = ROOT / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(content)
    print(f'{len(expected)} fichiers générés')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
